import re


def _scalar(s):
    s = s.strip()
    if not s:
        return None
    if s in ('null', 'Null', 'NULL', '~'):
        return None
    if s.lower() == 'true': return True
    if s.lower() == 'false': return False
    if s.startswith(('"', "'")):
        try:
