        elif c in "'\"": quote=c
        elif c in '[{(': depth+=1
        elif c in ']})': depth-=1
        elif c==',' and depth==0: out.append(s[start:i]); start=i+1
    out.append(s[start:]); return out


def parse_yaml(text):
    lines=[]
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#') or raw.strip() in ('---','...'): continue
        # remove comments outside quotes
        quote=None; cut=len(raw)
        for i,c in enumerate(raw):
            if quote:
                if c==quote: quote=None
            elif c in "'\"": quote=c
            elif c=='#' and (i==0 or raw[i-1].isspace()): cut=i; break
        raw=raw[:cut].rstrip()
        if raw.strip(): lines.append((len(raw)-len(raw.lstrip()),raw.lstrip()))
    if not lines: return None
    def parse(i, indent):
        islist=lines[i][1]=='-' or lines[i][1].startswith('- ')
        result=[] if islist else {}
        while i<len(lines) and lines[i][0]==indent:
            s=lines[i][1]
