"""Built-in functions observed in Dasel selectors.

The query evaluator can call ``call_function(name, args, current=...)`` for
ordinary function calls.  Chained calls pass the selected value as current.
"""

class FunctionError(ValueError):
    pass


def call_function(name, args, current=None):
    """Evaluate a built-in function over already evaluated arguments."""
    if name in ("keys", "values"):
        if args:
            raise FunctionError(f'func "{name}" expects exactly 0 arguments, got {len(args)}')
        if current is None:
