            x=s[i+1:j].strip()
            if x.startswith(('"',"'")):
                try: x=json.loads(x.replace("'",'"'))
                except: x=x[1:-1]
                parts.append(('key',x))
            else: parts.append(('index',int(x)))
            i=j+1
