def eval_expr(expr, item):
    expr=expr.strip()
    if expr.startswith("$this"):
        expr="item"+expr[5:]
    elif re.fullmatch(r"[A-Za-z_][\w-]*",expr):
        if isinstance(item,dict):
            if expr not in item: raise ValueError(f'map key not found: "{expr}"')
            return item[expr]
