def collection_query(data, query):
    m=re.fullmatch(r"(.+?)\.(filter|map|each|any|all|count)\((.*)\)",query)
    if not m: return None,False
    path,op,expr=m.groups(); seq=select(data,parse_selector(path))
    if not isinstance(seq,list): raise ValueError(f"unexpected type: expected array, got {type(seq).__name__}")
    if op=="filter": return [x for x in seq if eval_expr(expr,x)],True
