"""Helpers for Dasel recursive descent and search selectors.

These operate on ordinary Python JSON-like values and are kept separate from
the query parser so the CLI implementation can use them directly.
"""

def _children(value):
    if isinstance(value, dict):
        return value.values()
    if isinstance(value, list):
        return value
    return ()


def recursive_values(root, key):
    """Return values at key in descendant objects, in depth-first order.

    The root object's own keys are not considered by the reference `..key`
    selector; its children are searched.
    """
    out = []
    def walk(value):
        if isinstance(value, dict):
            for k, v in value.items():
                if k == key:
                    out.append(v)
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
    for child in _children(root):
        walk(child)
    return out


def search_objects(root, key, operator, expected):
    """Find descendant objects whose direct property satisfies a comparison."""
    def matches(value):
        if key not in value:
            return False
        actual = value[key]
        try:
            # Go's JSON-backed value comparisons keep booleans distinct from
            # numbers (Python's bool is an int subclass).
            if operator in ('==', '!='):
                equal = _json_equal(actual, expected)
                return equal if operator == '==' else not equal
            return {
                '>': lambda: actual > expected,
                '<': lambda: actual < expected,
                '>=': lambda: actual >= expected,
                '<=': lambda: actual <= expected,
            }[operator]()
        except (KeyError, TypeError):
            return False

    out = []
    def walk(value):
        if isinstance(value, dict):
            if matches(value):
                out.append(value)
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)
    # As with recursive descent, the top level itself isn't a candidate.
    for child in _children(root):
        walk(child)
    return out


def _json_equal(left, right):
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(_json_equal(left[k], right[k]) for k in left)
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(_json_equal(a, b) for a, b in zip(left, right))
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    return type(left) is type(right) and left == right

