"""Standard-library CSV and default XML adapters."""
import csv
import io
import xml.etree.ElementTree as ET
import json


def parse_csv(text, delimiter=','):
    reader = csv.DictReader(io.StringIO(text), delimiter=delimiter)
    return [{str(k): (v if v is not None else '') for k, v in row.items() if k is not None}
            for row in reader]


def _element(el):
    obj = {'-' + k: v for k, v in el.attrib.items()}
    children=list(el)
    text_parts = [el.text or '']
    for child in children:
        text_parts.append(child.tail or '')
    text = ''.join(text_parts)
    if not children and not obj:
        return text if text.strip() else ''
    if text:
        obj['#text'] = text
    for child in children:
        value = _element(child)
        key = child.tag
        if key in obj:
            old = obj[key]
            if not isinstance(old, list): old = [old]
            old.append(value)
            obj[key] = old

