    if isinstance(v, dict):
        items=[_key(str(k)) + " = " + _value(x) for k, x in v.items() if x is not None]
        return "{" + ", ".join(items) + "}"
    if v is None:
        raise ValueError("toml encode failed: toml: cannot encode a nil interface")
    return _value(str(v))


def dump_toml(value: Any, compact: bool = False) -> str:
    """Serialize a data tree as TOML, using tables for nested mappings."""
    if value is None:
        raise ValueError("toml encode failed: toml: cannot encode a nil interface")
    if not isinstance(value, dict):
        if isinstance(value, list) and all(isinstance(x, dict) for x in value):
            chunks=[]
            for idx,item in enumerate(value):
                if idx: chunks.append("")
                chunks.append("[[]]")
