        # Scalars, arrays of scalars, and inline maps first.
        children = []
        for k, v in table.items():
            if v is None: continue
            if isinstance(v, dict):
                children.append((str(k), v, False))
            elif isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                children.append((str(k), v, True))
            else:
                chunks.append(_key(str(k)) + " = " + _value(v))
        for k, child, is_array in children:
            if chunks and chunks[-1] != "": chunks.append("")
            if is_array:
                for index, item in enumerate(child):
                    if index and chunks and chunks[-1] != "": chunks.append("")
                    emit(item, path + [k], True)
            else:
                emit(child, path + [k])

    emit(value, [])
    return "\n".join(chunks).rstrip() + "\n"

